svg.script:
(function(){
const NS='http://www.w3.org/2000/svg', svg=document.documentElement;
function el(t,a,p){const e=document.createElementNS(NS,t);for(const k in a)e.setAttribute(k,a[k]);if(p)p.appendChild(e);return e;}
function ticks(lo,hi,n){if(!(hi>lo))return[lo];const raw=(hi-lo)/n,mag=Math.pow(10,Math.floor(Math.log10(raw)));
 let step=mag*10;for(const m of[1,2,5,10]){if(m*mag>=raw){step=m*mag;break;}}
 const first=Math.ceil(lo/step-1e-9)*step,out=[];for(let i=0;first+i*step<=hi+1e-9*step;i++)out.push(first+i*step);return out;}
function fmt(v,step){const d=Math.max(0,-Math.floor(Math.log10(step)+1e-9));return v.toFixed(d);}
const panels=[...svg.querySelectorAll('g.panel')].map(g=>{
 const d=k=>parseFloat(g.dataset[k]);
 const P={g,L:d('l'),R:d('r'),T:d('t'),B:d('b'),x0:d('x0'),x1:d('x1'),y0:d('y0'),y1:d('y1'),fixy:g.dataset.fixy==='1',link:g.dataset.link};
 P.home=[P.x0,P.x1,P.y0,P.y1];
 P.series=[...g.querySelectorAll('polyline.ln')].map(pl=>{
  const nums=pl.getAttribute('points').trim().split(/[\s,]+/).map(Number),n=nums.length/2,x=new Float64Array(n),y=new Float64Array(n);
  for(let i=0;i<n;i++){x[i]=P.x0+(nums[2*i]-P.L)/(P.R-P.L)*(P.x1-P.x0);y[i]=P.y0+(P.B-nums[2*i+1])/(P.B-P.T)*(P.y1-P.y0);}
  const ord=Array.from(x.keys()).sort((a,b)=>x[a]-x[b]);
  return {pl,x,y,ord,label:pl.dataset.label,colour:pl.getAttribute('stroke')};});
 P.refs=[...g.querySelectorAll('line.ref')];
 P.ax=g.querySelector('g.ax');
 P.hover=el('g',{class:'hv',visibility:'hidden'},g);
 P.vline=el('line',{y1:P.T,y2:P.B,stroke:'#59636e','stroke-width':1},P.hover);
 P.dots=P.series.map(s=>el('circle',{r:4,fill:s.colour,stroke:'#fff','stroke-width':2},P.hover));
 P.box=el('g',{},P.hover);
 P.sel=el('rect',{class:'hv',y:P.T,height:P.B-P.T,fill:'#2a78d6',opacity:0.12,visibility:'hidden'},g);
 P.hit=el('rect',{x:P.L,y:P.T,width:P.R-P.L,height:P.B-P.T,fill:'transparent',style:'cursor:crosshair'},g);
 return P;});
const sx=(P,v)=>P.L+(v-P.x0)/(P.x1-P.x0)*(P.R-P.L), sy=(P,v)=>P.B-(v-P.y0)/(P.y1-P.y0)*(P.B-P.T);
function draw(P){
 for(const s of P.series){const pts=[];const pad=(P.x1-P.x0)*0.01;
  for(let i=0;i<s.x.length;i++){const v=s.x[i];if(v>=P.x0-pad&&v<=P.x1+pad)pts.push(sx(P,v).toFixed(2)+','+sy(P,s.y[i]).toFixed(2));else if(pts.length&&pts[pts.length-1]!=='')pts.push('');}
  s.pl.setAttribute('points',pts.filter(p=>p).join(' '));}
 for(const r of P.refs){const y=sy(P,parseFloat(r.dataset.y));r.setAttribute('y1',y);r.setAttribute('y2',y);}
 while(P.ax.firstChild)P.ax.removeChild(P.ax.firstChild);
 const xt=ticks(P.x0,P.x1,6),yt=ticks(P.y0,P.y1,5),xs=xt.length>1?xt[1]-xt[0]:1,ys=yt.length>1?yt[1]-yt[0]:1;
 for(const v of xt){const x=sx(P,v);el('line',{class:'g',x1:x,x2:x,y1:P.T,y2:P.B},P.ax);
  el('text',{class:'m',x:x,y:P.B+16,'text-anchor':'middle'},P.ax).textContent=fmt(v,xs);}
 for(const v of yt){const y=sy(P,v);el('line',{class:'g',x1:P.L,x2:P.R,y1:y,y2:y},P.ax);
  el('text',{class:'m',x:P.L-6,y:y+4,'text-anchor':'end'},P.ax).textContent=fmt(v,ys);}}
function zoom(P,a,b){
 for(const Q of panels){if(Q!==P&&!(P.link&&Q.link===P.link))continue;
  Q.x0=a;Q.x1=b;
  if(!Q.fixy){let lo=Infinity,hi=-Infinity;
   for(const s of Q.series)for(let i=0;i<s.x.length;i++){if(s.x[i]>=a&&s.x[i]<=b){const v=s.y[i];if(v<lo)lo=v;if(v>hi)hi=v;}}
   for(const r of Q.refs){const v=parseFloat(r.dataset.y);if(v<lo)lo=v;if(v>hi)hi=v;}
   if(hi>lo){const m=0.04*(hi-lo);Q.y0=lo-m;Q.y1=hi+m;}}
  draw(Q);}}
function reset(P){for(const Q of panels){if(Q!==P&&!(P.link&&Q.link===P.link))continue;[Q.x0,Q.x1,Q.y0,Q.y1]=Q.home;draw(Q);}}
function local(evt){const pt=svg.createSVGPoint();pt.x=evt.clientX;pt.y=evt.clientY;return pt.matrixTransform(svg.getScreenCTM().inverse());}
function nearest(s,v){let lo=0,hi=s.ord.length-1;while(hi-lo>1){const m=(lo+hi)>>1;if(s.x[s.ord[m]]<v)lo=m;else hi=m;}
 const a=s.ord[lo],b=s.ord[hi];return Math.abs(s.x[a]-v)<Math.abs(s.x[b]-v)?a:b;}
function hover(P,px){
 const v=P.x0+(px-P.L)/(P.R-P.L)*(P.x1-P.x0),xt=ticks(P.x0,P.x1,6),step=(xt.length>1?xt[1]-xt[0]:1)/10;
 P.vline.setAttribute('x1',px);P.vline.setAttribute('x2',px);
 const rows=[['x = '+fmt(v,step),null]];
 P.series.forEach((s,k)=>{const d=P.dots[k];if(!s.x.length){d.setAttribute('visibility','hidden');return;}
  const i=nearest(s,v);const yy=sy(P,s.y[i]);
  if(Math.abs(s.x[i]-v)>(P.x1-P.x0)*0.02||yy<P.T||yy>P.B){d.setAttribute('visibility','hidden');return;}
  d.setAttribute('visibility','visible');d.setAttribute('cx',sx(P,s.x[i]));d.setAttribute('cy',yy);
  const yt=ticks(P.y0,P.y1,5);rows.push([s.label+': '+fmt(s.y[i],(yt.length>1?yt[1]-yt[0]:1)/100),s.colour]);});
 while(P.box.firstChild)P.box.removeChild(P.box.firstChild);
 const w=Math.max(...rows.map(r=>r[0].length))*7+28,h=rows.length*17+8,bx=px+12+w>P.R?px-12-w:px+12;
 el('rect',{x:bx,y:P.T+6,width:w,height:h,rx:4,fill:'#ffffff',stroke:'#c9cdd2'},P.box);
 rows.forEach((r,k)=>{const y=P.T+6+17*(k+1);
  if(r[1])el('rect',{x:bx+8,y:y-9,width:10,height:3,fill:r[1]},P.box);
  el('text',{x:bx+(r[1]?22:8),y:y,'font-size':12},P.box).textContent=r[0];});}
for(const P of panels){let drag=null;
 P.hit.addEventListener('mousemove',e=>{const px=Math.min(P.R,Math.max(P.L,local(e).x));P.hover.setAttribute('visibility','visible');hover(P,px);
  if(drag!==null){P.sel.setAttribute('x',Math.min(drag,px));P.sel.setAttribute('width',Math.abs(px-drag));P.sel.setAttribute('visibility','visible');}});
 P.hit.addEventListener('mouseleave',()=>{P.hover.setAttribute('visibility','hidden');P.sel.setAttribute('visibility','hidden');drag=null;});
 P.hit.addEventListener('mousedown',e=>{drag=Math.min(P.R,Math.max(P.L,local(e).x));e.preventDefault();});
 P.hit.addEventListener('mouseup',e=>{if(drag===null)return;const px=Math.min(P.R,Math.max(P.L,local(e).x));P.sel.setAttribute('visibility','hidden');
  if(Math.abs(px-drag)>4){const f=p=>P.x0+(p-P.L)/(P.R-P.L)*(P.x1-P.x0);zoom(P,f(Math.min(px,drag)),f(Math.max(px,drag)));}drag=null;});
 P.hit.addEventListener('dblclick',()=>reset(P));}
})();
